(function (root) {
  "use strict";
  // Source artwork, sized for lettering overlays. Embedded for standalone SVG/PNG export.
  const artwork = {
    1: [201, 234, ""],
    2: [156, 97, ""],
    3: [42, 93, ""],
    4: [208, 250, ""],
    5: [157, 320, ""],
    6: [126, 130, ""],
    7: [111, 120, ""],
    8: [59, 88, ""],
    9: [72, 60, ""],
    10: [102, 84, ""],
    11: [80, 100, ""],
    12: [202, 178, ""],
    13: [131, 220, ""],
    14: [129, 141, ""],
    15: [163, 188, ""],
    16: [198, 195, ""],
    17: [122, 147, ""],
    18: [228, 221, ""],
    19: [154, 223, ""],
    20: [214, 235, ""],
    21: [119, 122, ""],
    22: [102, 158, ""],
    23: [320, 281, ""],
    24: [115, 158, ""],
    25: [274, 210, ""],
    26: [83, 123, ""],
    27: [232, 274, ""],
    28: [96, 154, ""]
  };
  const aliases = new Map(Object.entries({
    '톡톡': 1, '충격표시': 2, '짧은곡선': 3, '똑똑': 4, '스윽': 5, '스으윽': 5,
    '꾸벅': 6, '척': 7, '?': 8, '물음표': 8, '짧은화살표': 9, '저': 10, '흠': 11,
    '끼익': 12, '슥': 13, '탁': 14, '척!': 15, '덜컹': 16, '헉': 17, '터엉': 18,
    '끼익…': 19, '턱': 20, '텅': 21, '작은슥': 22, '끼이익': 23, '똑': 24,
    '탁—': 25, '긴곡선': 26, '덜컹—': 27, '톡': 28,
  }));

  function match(text) {
    const original = text.normalize('NFKC').replace(/\s+/g, '');
    const key = original
      .replace(/[.]{2,}$/u, '…')
      .replace(/[~—–―ー]+$/u, '—')
      .replace(/!+$/u, '!');
    const letter = key.replace(/[…]$/u, '').replace(/[.!?—]+$/u, '');
    const id = aliases.get(key) ?? aliases.get(letter);
    if (!id) return null;
    const [width, height, bytes] = artwork[id];
    return {width, height, src: 'data:image/png;base64,' + bytes};
  }

  root.RoughSoundEffects = {match};
})(typeof window === 'object' ? window : globalThis);
